function validateConfig(cfg) {
  if(cfg.diagnosticDetails!==undefined&&typeof cfg.diagnosticDetails!=='boolean')throw Error('diagnosticDetails must be boolean');
  if (['components','prepare','iterate','final'].indexOf(cfg.stage)<0) throw Error('Unknown stage');
  if (!/^[A-Za-z0-9_-]+$/.test(cfg.runId)) throw Error('Invalid runId');
  if (typeof cfg.assetRoot!=='string')
    throw Error('CONFIG.assetRoot 必须是原生 JavaScript 字符串，空字符串自动选择输入父目录，非空字符串指定临时状态输出目录；导入影像请放在 getFloodInput()，不能使用 ee.Image、ee.String 或列表作为目录');
  if (cfg.assetRoot.indexOf('YOUR_PROJECT')>=0 || /[<>]/.test(cfg.assetRoot))
    throw Error('请将 CONFIG.assetRoot 的占位路径替换为已创建、可写的 GEE 资产文件夹；它不是洪水输入');
  if (cfg.step<0 || cfg.step%1 || (cfg.stage==='iterate' && cfg.step<1)) throw Error('Invalid step');
  if (cfg.sweepsPerStage<1 || cfg.sweepsPerStage%1 || cfg.maxSweeps<2*cfg.sweepsPerStage ||
      cfg.maxSweeps%cfg.sweepsPerStage) throw Error('Invalid sweep schedule');
  ['lambdaC','lambdaB','lambdaT','sigmaFloor','slopeScaleDeg','dispersionScaleMeters',
    'residualTolerance','objectiveTolerance','objectiveFloor','budgetRelative','budgetAbsolute'].forEach(function(k){
    if (!(cfg[k]>0) || !isFinite(cfg[k])) throw Error('Invalid parameter '+k);
  });
  ['pairRadius','peerRadius','minSamplesPerSide','minAnchors','minSpanPixels'].forEach(function(k){
    if (!(cfg[k]>=1)||cfg[k]%1) throw Error('Expected positive integer '+k);
  });
  if (!(cfg.highWeight>0&&cfg.highWeight<=1) || !(cfg.minDepth>=0) || !isFinite(cfg.minDepth))
    throw Error('Invalid boundary weight/depth threshold');
  if (!cfg.muRatios.length) throw Error('At least one secondary attempt is required');
  cfg.muRatios.forEach(function(r,i){if (!(r>0&&r<1)||(i&&r>=cfg.muRatios[i-1])) throw Error('muRatios must decrease in (0,1)');});
  if (!(cfg.noData<0)||cfg.step>99999) throw Error('Invalid NoData/state index');
}

