function resolveAssetLocation(cfg,input,getAsset,listAssets) {
  var sourceId=cfg.fixture?null:input.get('system:id').getInfo();
  if (sourceId) {
    checkAssetPath(sourceId,true);
    var source=getAsset(sourceId);
    requireAssetType(source,sourceId,'IMAGE');
  }
  if (!cfg.assetRoot && !sourceId)
    throw Error('无法自动确定目录：合成场景或无资产 ID 的计算影像必须显式设置 CONFIG.assetRoot；inputRevision 不能代替目录');
  var root=cfg.assetRoot || sourceId.slice(0,sourceId.lastIndexOf('/'));
  checkAssetPath(root,false);
  // 项目根目录不是普通文件夹资产；用有界列表请求确认可访问性，空目录也有效。
  if (/^projects\/[^/]+\/assets$/.test(root)) {
    var listing=listAssets(root,{pageSize:1});
    if (!listing || typeof listing!=='object' || Array.isArray(listing) ||
        (listing.assets!==undefined && !Array.isArray(listing.assets)))
      throw Error('Invalid project asset listing: '+root);
  } else {
    requireAssetType(getAsset(root),root,'FOLDER');
  }
  return {root:root,sourceId:sourceId}; // 可读不代表可写；写权限由导出任务验证。
}

