  var state=['S','baseS'].concat(STATE_FIELDS);
  if(kind==='components')return components;
  if(kind==='prepared')return components.concat(['lower','upper','mid','weight','eligible'],state);
  if(kind==='state')return state;
  throw Error('Unknown stage asset kind: '+kind);
